<?php
namespace App\Http\Controllers\Admin;
use Illuminate\Support\Facades\Cache;
use App\Http\Controllers\Controller; use App\Models\City; use App\Models\Province; use Illuminate\Http\Request;
class CityController extends Controller { public function index(){return view('admin.cities.index',['cities'=>City::with('province')->orderBy('province_id')->orderBy('name')->paginate(30)]);} public function create(){return view('admin.cities.form',['city'=>new City,'provinces'=>Province::orderBy('name')->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:255','province_id'=>'required|exists:provinces,id']);City::create($d);Cache::forget('province:'.$d['province_id'].':cities');return redirect()->route('admin.cities.index')->with('success','شهر ایجاد شد.');} public function edit(City $city){return view('admin.cities.form',['city'=>$city,'provinces'=>Province::orderBy('name')->get()]);} public function update(Request $r,City $city){$oldProvince=$city->province_id;$d=$r->validate(['name'=>'required|max:255','province_id'=>'required|exists:provinces,id']);$city->update($d);Cache::forget('province:'.$oldProvince.':cities');Cache::forget('province:'.$d['province_id'].':cities');return redirect()->route('admin.cities.index')->with('success','شهر ویرایش شد.');} public function destroy(City $city){if($city->ads()->exists())return back()->with('error','این شهر آگهی دارد و قابل حذف نیست.');$provinceId=$city->province_id;$city->delete();Cache::forget('province:'.$provinceId.':cities');return back()->with('success','حذف شد.');} }
